'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const positions = new Array(n);
let total = 0;

for (let i = 0; i < n; i++) {
  positions[i] = total;
  total += input[i + 1];
}

if (total % 2 !== 0) {
  console.log('N');
} else {
  const half = total / 2;
  const indexByPosition = new Map();

  for (let i = 0; i < n; i++) {
    indexByPosition.set(positions[i], i);
  }

  let pairs = 0;
  for (let i = 0; i < n; i++) {
    let opposite = positions[i] + half;
    if (opposite >= total) opposite -= total;

    const j = indexByPosition.get(opposite);
    if (j !== undefined && j > i) pairs++;
  }

  console.log(pairs >= 2 ? 'S' : 'N');
}
